// ==== PRISMA: lata de sabores, refraccion y sonido ========================
//
// Un prisma parte la luz blanca en colores. PRISMA parte el te en sabores.
// Girar la cabeza cambia el angulo de refraccion: cambia el sabor de la lata,
// su color y el tinte de la cara. Los gestos de la cara disparan los sonidos.
//
// Gestos:
//   girar la cabeza a un lado  -> sabor anterior / siguiente
//   levantar la cabeza         -> siguiente sabor
//   abrir la boca              -> sonido distintivo del sabor
//   levantar las cejas         -> abrir la lata (psst)
//   sonreir                    -> destello
//
// En el scope hay: this (el grupo Lata), scene, camera, renderer, player, THREE
// y, dentro de los eventos de cara, el objeto global `face`.

// ---- Sabores -------------------------------------------------------------
// Para cambiar la paleta o los nombres solo hay que tocar esta lista.
const SABORES = [
	{
		nombre: 'Ámbar',
		receta: 'Mandarina y té negro',
		nota: 'Cáscara, caramelo y un final seco.',
		cafeina: '45 mg de cafeína',
		color: 0xffa23a,
		onda: 'triangle',
		notas: [392.00, 587.33, 783.99]
	},
	{
		nombre: 'Lima',
		receta: 'Hierbabuena y té verde',
		nota: 'Frío en la boca, herbal, muy ligero.',
		cafeina: '28 mg de cafeína',
		color: 0x6fe86b,
		onda: 'sine',
		notas: [440.00, 659.25, 987.77]
	},
	{
		nombre: 'Índigo',
		receta: 'Mora y té oolong',
		nota: 'Fruta oscura con fondo tostado.',
		cafeina: '35 mg de cafeína',
		color: 0x7a6bff,
		onda: 'sawtooth',
		notas: [261.63, 392.00, 523.25]
	},
	{
		nombre: 'Magenta',
		receta: 'Maracuyá y té blanco',
		nota: 'Ácido alto, dulce corto, floral.',
		cafeina: '18 mg de cafeína',
		color: 0xff4f93,
		onda: 'square',
		notas: [329.63, 493.88, 740.00]
	}
];

// ---- Ajustes -------------------------------------------------------------
const GIRO_CAMBIA = 0.34;    // radianes de giro lateral para cambiar de sabor
const ALZAR_CAMBIA = 0.30;   // radianes de cabeza arriba para cambiar
const REPOSO = 0.16;         // hay que volver al centro antes del proximo cambio
const ESPERA = 420;          // ms minimos entre dos cambios
const INVERTIR_GIRO = false; // ponlo en true si los lados salen al reves
const DISTANCIA = 0.26;      // que tan lejos sale la lata hacia la camara
const ALTURA = 0.60;         // medido desde la nariz: 0.60 la deja sobre la frente
const LADO = 0;              // desplazamiento a un lado (0 = centrada)
const COPIAS = 3;            // veces que se repite la etiqueta alrededor
const ALTO = 0.50;           // alto de la lata; se construye normalizada a 1

// ---- Estado --------------------------------------------------------------
let grupo = null;        // el grupo Lata (this)
let cuerpo = null;       // cilindro con la etiqueta
let cara = null;         // mesh_0
let materialCara = null;
let texturaCara = null;  // la textura que trae el JSON
const texturasSabor = {};
const cargador = new THREE.TextureLoader();
let lienzo = null;       // canvas de la etiqueta
let pincel = null;
let texturaEtiqueta = null;

let indice = 0;
let armado = true;
let ultimoCambio = -9999;
let reloj = 0;
let giroExtra = 0;       // vuelta que da la lata al cambiar
let destello = 0;
let aparicion = 0;
let hayCara = false;

const colorAhora = new THREE.Color(SABORES[0].color);
const colorMeta = new THREE.Color(SABORES[0].color);

// Vectores reutilizados (no se crean dentro del bucle).
const vNariz = new THREE.Vector3();
const vOjoIzq = new THREE.Vector3();
const vOjoDer = new THREE.Vector3();
const vFrente = new THREE.Vector3();
const vMenton = new THREE.Vector3();
const ejeX = new THREE.Vector3();
const ejeY = new THREE.Vector3();
const ejeZ = new THREE.Vector3();
const destinoLata = new THREE.Vector3();
const centroLata = new THREE.Vector3();
const bordeLata = new THREE.Vector3();
const rayo = new THREE.Raycaster();
const puntero = new THREE.Vector2();

// Indices del mapa canonico de MediaPipe.
const PUNTA_NARIZ = 1;
const OJO_IZQ = 33;
const OJO_DER = 263;
const FRENTE = 10;
const MENTON = 152;

// ---- Sonido --------------------------------------------------------------
// Todo se sintetiza con WebAudio: no hay que subir ningun mp3 al servidor.
// Si prefieres sonidos grabados, usa player.loadAudio(nombre, url) como en el
// ejemplo del gato y llama a sound.play() dentro de cada gesto.
let audio = null;

function motor() {
	if (audio === null) {
		// En iOS esto saca el sonido por el altavoz y lo libra del
		// interruptor de silencio. La pagina lo repite por su cuenta.
		if (navigator.audioSession) {
			try { navigator.audioSession.type = 'playback'; } catch (e) { }
		}
		const AC = window.AudioContext || window.webkitAudioContext;
		if (!AC) return null;
		audio = new AC();
	}
	if (audio.state === 'suspended') audio.resume();
	return audio;
}

// Los navegadores bloquean el audio hasta que la persona toca la pagina.
document.addEventListener('pointerdown', motor);
document.addEventListener('keydown', motor);

function tono(frecuencia, forma, retraso, duracion, volumen) {
	const ac = motor();
	if (!ac) return;
	const t = ac.currentTime + retraso;
	const osc = ac.createOscillator();
	const vol = ac.createGain();
	osc.type = forma;
	osc.frequency.setValueAtTime(frecuencia, t);
	vol.gain.setValueAtTime(0.0001, t);
	vol.gain.exponentialRampToValueAtTime(volumen, t + 0.012);
	vol.gain.exponentialRampToValueAtTime(0.0001, t + duracion);
	osc.connect(vol).connect(ac.destination);
	osc.start(t);
	osc.stop(t + duracion + 0.05);
}

function ruido(duracion, desde, hasta, volumen) {
	const ac = motor();
	if (!ac) return;
	const t = ac.currentTime;
	const muestras = Math.floor(ac.sampleRate * duracion);
	const buffer = ac.createBuffer(1, muestras, ac.sampleRate);
	const datos = buffer.getChannelData(0);
	for (let i = 0; i < muestras; i++) {
		datos[i] = (Math.random() * 2 - 1) * (1 - i / muestras);
	}
	const fuente = ac.createBufferSource();
	fuente.buffer = buffer;
	const filtro = ac.createBiquadFilter();
	filtro.type = 'bandpass';
	filtro.Q.value = 1.4;
	filtro.frequency.setValueAtTime(desde, t);
	filtro.frequency.exponentialRampToValueAtTime(hasta, t + duracion);
	const vol = ac.createGain();
	vol.gain.setValueAtTime(volumen, t);
	vol.gain.exponentialRampToValueAtTime(0.0001, t + duracion);
	fuente.connect(filtro).connect(vol).connect(ac.destination);
	fuente.start(t);
	fuente.stop(t + duracion + 0.05);
}

// Sonido propio de cada sabor: tres notas con la onda de ese sabor.
function firma(sabor) {
	sabor.notas.forEach((nota, i) => tono(nota, sabor.onda, i * 0.085, 0.42, 0.16));
	ruido(0.5, 2600, 7000, 0.10);
}

// Cambio de sabor: la luz se refracta.
function refraccion(sabor) {
	tono(sabor.notas[0] * 2, 'sine', 0, 0.16, 0.11);
	ruido(0.26, 900, 5200, 0.09);
}

// Abrir la lata.
function destapar() {
	ruido(0.42, 5200, 700, 0.22);
	ruido(0.9, 1800, 3400, 0.06);
}

// ---- Etiqueta de la lata -------------------------------------------------
// La etiqueta se dibuja en un canvas, asi que no hay imagenes que cargar y el
// sabor se puede repintar al vuelo.
// Texto con separacion entre letras, dibujado letra a letra para que se vea
// igual en todos los navegadores (canvas.letterSpacing no existe en todos).
function textoEspaciado(texto, centroX, y, separacion) {
	const letras = texto.split('');
	let ancho = 0;
	for (const l of letras) ancho += pincel.measureText(l).width + separacion;
	ancho -= separacion;
	let x = centroX - ancho / 2;
	for (const l of letras) {
		pincel.fillText(l, x, y);
		x += pincel.measureText(l).width + separacion;
	}
}

function dibujarEtiqueta(sabor) {
	if (!pincel) return;
	const W = lienzo.width;
	const H = lienzo.height;
	const color = new THREE.Color(sabor.color);
	const claro = color.clone().lerp(new THREE.Color(0xffffff), 0.30).getStyle();
	const oscuro = color.clone().lerp(new THREE.Color(0x120c1f), 0.55).getStyle();

	const fondo = pincel.createLinearGradient(0, 0, 0, H);
	fondo.addColorStop(0, claro);
	fondo.addColorStop(0.45, color.getStyle());
	fondo.addColorStop(1, oscuro);
	pincel.fillStyle = fondo;
	pincel.fillRect(0, 0, W, H);

	for (let copia = 0; copia < COPIAS; copia++) {
		pincel.save();
		pincel.translate(copia * W / COPIAS, 0);
		const w = W / COPIAS;

		// Prisma: un triangulo con el haz de luz saliendo en colores.
		// El prisma de la marca: el triangulo y los rayos que salen de el.
		pincel.globalAlpha = 0.32;
		pincel.fillStyle = '#ffffff';
		pincel.beginPath();
		pincel.moveTo(w * 0.5, H * 0.12);
		pincel.lineTo(w * 0.68, H * 0.44);
		pincel.lineTo(w * 0.32, H * 0.44);
		pincel.closePath();
		pincel.fill();

		pincel.strokeStyle = '#ffffff';
		pincel.lineCap = 'round';
		pincel.lineWidth = Math.max(2, H * 0.009);
		[[0.22, 0.62], [0.30, 0.78], [0.38, 0.54], [0.46, 0.40]].forEach(([dy, alfa], i) => {
			pincel.globalAlpha = alfa * 0.55;
			pincel.beginPath();
			pincel.moveTo(w * 0.60, H * 0.40);
			pincel.lineTo(w * (0.78 + i * 0.045), H * (0.40 + dy));
			pincel.stroke();
		});
		pincel.globalAlpha = 1;

		pincel.fillStyle = 'rgba(255,255,255,0.94)';
		pincel.textAlign = 'left';
		pincel.font = '700 ' + Math.round(H * 0.170) + 'px Archivo, Helvetica, Arial, sans-serif';
		textoEspaciado('PRISMA', w * 0.5, H * 0.63, Math.round(H * 0.042));

		pincel.textAlign = 'center';
		pincel.font = '500 ' + Math.round(H * 0.100) + 'px Archivo, Helvetica, Arial, sans-serif';
		pincel.fillStyle = 'rgba(255,255,255,0.88)';
		pincel.fillText(sabor.nombre, w * 0.5, H * 0.78);

		pincel.font = '500 ' + Math.round(H * 0.052) + 'px Archivo, Helvetica, Arial, sans-serif';
		pincel.fillStyle = 'rgba(255,255,255,0.62)';
		pincel.fillText('te con gas  ·  ' + sabor.receta, w * 0.5, H * 0.89);

		pincel.restore();
	}

	if (texturaEtiqueta) texturaEtiqueta.needsUpdate = true;
}

// ---- Montaje de la lata --------------------------------------------------
// La malla viene dentro del JSON (el modelo de lata, normalizado a 1 de alto).
// Aqui solo se le pone la etiqueta dibujada y el resplandor de atras.
function construirLata() {
	lienzo = document.createElement('canvas');
	lienzo.width = 2048;
	lienzo.height = 512;
	pincel = lienzo.getContext('2d');

	texturaEtiqueta = new THREE.CanvasTexture(lienzo);
	texturaEtiqueta.anisotropy = 8;
	texturaEtiqueta.wrapS = THREE.RepeatWrapping;
	if ('colorSpace' in texturaEtiqueta) texturaEtiqueta.colorSpace = THREE.SRGBColorSpace;
	dibujarEtiqueta(SABORES[indice]);

	cuerpo = grupo.getObjectByName('etiqueta');
	if (cuerpo) {
		cuerpo.material.map = texturaEtiqueta;
		cuerpo.material.needsUpdate = true;
	} else {
		console.warn('PRISMA: no encontre la malla "etiqueta" dentro del grupo Lata');
	}

	// Resplandor detras de la lata: un degradado, no un circulo plano.
	const lienzoHalo = document.createElement('canvas');
	lienzoHalo.width = lienzoHalo.height = 256;
	const brocha = lienzoHalo.getContext('2d');
	const degradado = brocha.createRadialGradient(128, 128, 6, 128, 128, 126);
	degradado.addColorStop(0, 'rgba(255,255,255,0.80)');
	degradado.addColorStop(0.35, 'rgba(255,255,255,0.26)');
	degradado.addColorStop(1, 'rgba(255,255,255,0)');
	brocha.fillStyle = degradado;
	brocha.fillRect(0, 0, 256, 256);

	const halo = new THREE.Mesh(
		new THREE.PlaneGeometry(1.9, 1.9),
		new THREE.MeshBasicMaterial({
			map: new THREE.CanvasTexture(lienzoHalo),
			color: SABORES[indice].color,
			transparent: true,
			opacity: 0.5,
			blending: THREE.AdditiveBlending,
			depthWrite: false
		})
	);
	halo.name = 'halo';
	halo.position.z = -0.4;
	grupo.add(halo);
}

// ---- Textura de la cara --------------------------------------------------
// Si pintaste texturas propias en studio.html, sus rutas se escriben en
// js/prisma/prisma_ui.js (window.PRISMA_TEXTURAS). Esa textura se muestra tal
// cual. Si no hay ninguna, se usa la de facetas del JSON teñida del color.
function rutaTextura(sabor) {
	const propias = (typeof window !== 'undefined' && window.PRISMA_TEXTURAS) || {};
	return propias[sabor.nombre] || sabor.textura || null;
}

function aplicarTextura(sabor) {
	if (!materialCara) return;
	const ruta = rutaTextura(sabor);

	// Las facetas que trae el JSON se suman como luz; una textura pintada por
	// ti se pinta encima con su alfa, que es como se vio en el estudio.
	materialCara.blending = ruta ? THREE.NormalBlending : THREE.AdditiveBlending;
	materialCara.opacity = ruta ? 0.95 : 1;

	if (!ruta) {
		materialCara.map = texturaCara;
		materialCara.needsUpdate = true;
		return;
	}

	const puesta = texturasSabor[ruta];
	if (puesta) {
		materialCara.map = puesta;
		materialCara.color.setHex(0xffffff);
		materialCara.needsUpdate = true;
		return;
	}

	cargador.load(ruta, (t) => {
		t.flipY = true;
		if ('colorSpace' in t) t.colorSpace = THREE.SRGBColorSpace;
		texturasSabor[ruta] = t;
		if (rutaTextura(SABORES[indice]) === ruta) {
			materialCara.map = t;
			materialCara.color.setHex(0xffffff);
			materialCara.needsUpdate = true;
		}
	}, undefined, () => console.warn('PRISMA: no se encontro la textura ' + ruta));
}

// ---- Aviso a la pagina ---------------------------------------------------
// La interfaz del HTML escucha estos eventos para escribir el sabor en
// pantalla y para abrir la ficha cuando se toca la lata.
function anunciar(evento, sabor) {
	window.dispatchEvent(new CustomEvent(evento, {
		detail: {
			indice: indice,
			nombre: sabor.nombre,
			receta: sabor.receta,
			nota: sabor.nota,
			cafeina: sabor.cafeina,
			color: '#' + sabor.color.toString(16).padStart(6, '0')
		}
	}));
}

// ---- Tocar la lata en la pantalla ----------------------------------------
// Se compara la posicion del dedo con la de la lata proyectada en pantalla.
// Es mas tolerante que lanzar un rayo contra la malla y no depende de como
// este escalado el lienzo.
function alTocar(evento) {
	if (!grupo || !hayCara) return;

	const caja = renderer.domElement.getBoundingClientRect();
	if (!caja.width || !caja.height) return;

	puntero.x = ((evento.clientX - caja.left) / caja.width) * 2 - 1;
	puntero.y = -((evento.clientY - caja.top) / caja.height) * 2 + 1;

	grupo.getWorldPosition(centroLata);
	bordeLata.copy(centroLata).addScaledVector(ejeY, 0.6 * grupo.scale.y);

	const centro = centroLata.clone().project(camera);
	const borde = bordeLata.clone().project(camera);
	if (centro.z > 1) return;

	const radio = Math.max(0.12, Math.hypot(borde.x - centro.x, borde.y - centro.y) * 1.5);
	const d = Math.hypot(puntero.x - centro.x, puntero.y - centro.y);
	if (d > radio) return;

	anunciar('prisma:info', SABORES[indice]);
	firma(SABORES[indice]);
	destello = 0.8;
	giroExtra = Math.PI * 0.6;
}

// ---- Cambio de sabor -----------------------------------------------------
function cambiarSabor(direccion) {
	indice = (indice + direccion + SABORES.length) % SABORES.length;
	const sabor = SABORES[indice];

	dibujarEtiqueta(sabor);
	aplicarTextura(sabor);
	colorMeta.setHex(sabor.color);
	giroExtra = Math.PI * 2 * (direccion >= 0 ? 1 : -1);
	ultimoCambio = reloj;
	refraccion(sabor);

	const halo = grupo.getObjectByName('halo');
	if (halo) halo.material.color.setHex(sabor.color);

	anunciar('prisma:sabor', sabor);
}

// ---- Orientacion de la cabeza --------------------------------------------
// Se calcula a partir de la propia malla de la cara, asi que funciona tanto si
// el controlador deforma los vertices como si mueve el objeto entero.
function puntoDeLaCara(indiceVertice, destino) {
	const posiciones = cara.geometry.attributes.position;
	destino.fromBufferAttribute(posiciones, indiceVertice);
	destino.applyMatrix4(cara.matrixWorld);
	return destino;
}

function medirCabeza() {
	if (!cara || !cara.geometry || !cara.geometry.attributes.position) return null;
	cara.updateWorldMatrix(true, false);

	puntoDeLaCara(PUNTA_NARIZ, vNariz);
	puntoDeLaCara(OJO_IZQ, vOjoIzq);
	puntoDeLaCara(OJO_DER, vOjoDer);
	puntoDeLaCara(FRENTE, vFrente);
	puntoDeLaCara(MENTON, vMenton);

	ejeX.subVectors(vOjoDer, vOjoIzq);
	if (ejeX.lengthSq() < 1e-10) return null;
	ejeX.normalize();

	ejeY.subVectors(vFrente, vMenton).normalize();
	ejeZ.crossVectors(ejeX, ejeY).normalize();          // sale de la cara
	ejeY.crossVectors(ejeZ, ejeX).normalize();          // se vuelve perpendicular

	const lado = Math.atan2(ejeZ.x, Math.abs(ejeZ.z) < 1e-5 ? 1e-5 : ejeZ.z);
	const arriba = Math.asin(THREE.MathUtils.clamp(ejeZ.y, -1, 1));

	return { lado: INVERTIR_GIRO ? -lado : lado, arriba: arriba };
}

// ---- Ciclo de vida -------------------------------------------------------
function start() {
	grupo = this;
	cara = scene.getObjectByName('mesh_0');
	if (cara && cara.material) {
		materialCara = cara.material;
		texturaCara = materialCara.map;
		materialCara.color.copy(colorAhora);
		aplicarTextura(SABORES[indice]);
	}
	construirLata();
	grupo.position.set(0, ALTURA * 0.4, DISTANCIA);
	renderer.domElement.addEventListener('pointerdown', alTocar);
	anunciar('prisma:sabor', SABORES[indice]);
}

function update(event) {
	const delta = event.delta;
	reloj += delta;

	// Entrada de la lata.
	aparicion = Math.min(1, aparicion + delta / 520);
	const entrada = 1 - Math.pow(1 - aparicion, 3);

	// Al cambiar de sabor da una vuelta; el resto del tiempo se queda
	// mirando al frente, balanceandose, para que la etiqueta se lea.
	if (Math.abs(giroExtra) > 0.004) {
		const paso = giroExtra * Math.min(1, delta / 260);
		grupo.rotation.y += paso;
		giroExtra -= paso;
	} else {
		if (giroExtra !== 0) {
			giroExtra = 0;
			// se normaliza el angulo para que no desande la vuelta
			grupo.rotation.y = ((grupo.rotation.y + Math.PI) % (Math.PI * 2)) - Math.PI;
		}
		const objetivo = Math.sin(reloj / 2600) * 0.20;
		grupo.rotation.y += (objetivo - grupo.rotation.y) * Math.min(1, delta / 420);
	}

	// Flota y se inclina un poco.
	const flote = Math.sin(reloj / 900) * 0.012;
	grupo.rotation.x = 0.10 + Math.sin(reloj / 1400) * 0.05;
	grupo.rotation.z = Math.sin(reloj / 1700) * 0.04;

	// Color: la cara y el halo se acercan al color del sabor.
	colorAhora.lerp(colorMeta, Math.min(1, delta / 260));
	if (materialCara && !rutaTextura(SABORES[indice])) materialCara.color.copy(colorAhora);

	// Destello al sonreir.
	destello = Math.max(0, destello - delta / 520);
	const escala = ALTO * entrada * (1 + destello * 0.34);
	grupo.scale.setScalar(escala);

	// La lata se coloca delante de la cara.
	const cabeza = hayCara ? medirCabeza() : null;
	if (cabeza) {
		destinoLata.copy(vNariz)
			.addScaledVector(ejeZ, DISTANCIA)
			.addScaledVector(ejeX, LADO)
			.addScaledVector(ejeY, ALTURA + flote);
		grupo.position.lerp(destinoLata, Math.min(1, delta / 120));
	} else {
		grupo.position.y = ALTURA * 0.4 + flote;
	}
}

// ---- Cara ----------------------------------------------------------------
function faceFound(event) {
	hayCara = true;
	aparicion = 0;
}

function faceLost(event) {
	hayCara = false;
	armado = true;
}

function faceUpdate(event) {
	const cabeza = medirCabeza();
	if (!cabeza) return;

	const quieta = Math.abs(cabeza.lado) < REPOSO && Math.abs(cabeza.arriba) < REPOSO;
	if (quieta) armado = true;
	if (!armado || reloj - ultimoCambio < ESPERA) return;

	if (cabeza.lado > GIRO_CAMBIA) {
		armado = false;
		cambiarSabor(1);
	} else if (cabeza.lado < -GIRO_CAMBIA) {
		armado = false;
		cambiarSabor(-1);
	} else if (cabeza.arriba > ALZAR_CAMBIA) {
		armado = false;
		cambiarSabor(1);
	}
}

